AFAnalysisRule.ConfigString:
Variable1 := if MID(Text('UM_Decapagem_Eletrolitica'), 7, 1) = "T" or Contains(Text('UM_Decapagem_Eletrolitica'), "BOB") then 3 else if 'Teor Fe|Teor Fe Inferior'= -999 or 'Teor Fe|Teor Fe Superior' = -999 then 3 else if 'Teor Fe' >= 'Teor Fe|Teor Fe Inferior' and 'Teor Fe' <= 'Teor Fe|Teor Fe Superior' then 1 else if 'Teor Fe' > 'Teor Fe|Teor Fe Superior' or 'Teor Fe' < 'Teor Fe|Teor Fe Inferior' then 2 else 3;
Variable2 := 'Teor Fe';
Variable3 := 'Teor Fe|Teor Fe Superior';
Variable4 := 'Teor Fe|Teor Fe Inferior';
